/**
 * Phase 5 (migration 0001_rate_limit_bucket): one fixed throttle window per (site, scope, key) —
 * capability abuse-protection, spec/data.md → rate_limit_bucket. `key_hash` is sha256 hex of the raw
 * key (never the email/IP itself); rows are ephemeral (pruned once expired, not backed up).
 */
export const rateLimitBucket = pgTable(
  'rate_limit_bucket',
  {
    siteId: uuid('site_id')
      .notNull()
      .references(() => site.id, { onDelete: 'cascade' }),
    scope: text('scope').notNull(),
    keyHash: text('key_hash').notNull(),
    windowStart: timestamp('window_start', { withTimezone: true }).notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    count: integer('count').notNull().default(0),
  },
  (t) => [
    primaryKey({ name: 'rate_limit_bucket_pk', columns: [t.siteId, t.scope, t.keyHash, t.windowStart] }),
    index('rate_limit_bucket_expires_idx').on(t.expiresAt),
    check('rate_limit_bucket_count_check', sql`${t.count} >= 0`),
  ],
);

