export type ArticleFormatRow = typeof articleFormat.$inferSelect;
export type AiGenerationRow = typeof aiGeneration.$inferSelect;
export type NewsletterSubscriberRow = typeof newsletterSubscriber.$inferSelect;
export type MediaAssetRow = typeof mediaAsset.$inferSelect;
export type RateLimitBucketRow = typeof rateLimitBucket.$inferSelect;

